begin;
select no_plan();
select has_table('public', 'merchants', 'merchant configuration exists');
select has_table('public', 'merchant_memberships', 'owner memberships exist');
select has_table('public', 'merchant_categories', 'categories exist');
select has_table('public', 'merchant_services', 'services exist');
select has_table('public', 'merchant_schedules', 'schedule aggregate exists');
select has_table('public', 'merchant_audit_events', 'audit history exists');
select ok(bool_and(relrowsecurity), 'all six tables enforce RLS') from pg_class where oid in ('merchants'::regclass,'merchant_memberships'::regclass,'merchant_categories'::regclass,'merchant_services'::regclass,'merchant_schedules'::regclass,'merchant_audit_events'::regclass);
select ok(relrowsecurity, relname || ' has RLS') from pg_class where oid in ('merchants'::regclass,'merchant_memberships'::regclass,'merchant_categories'::regclass,'merchant_services'::regclass,'merchant_schedules'::regclass,'merchant_audit_events'::regclass);
select ok(not has_table_privilege('anon', 'public.' || t, 'select'), t || ' denies anon') from unnest(array['merchants','merchant_memberships','merchant_categories','merchant_services','merchant_schedules','merchant_audit_events']) t;
select ok(not has_function_privilege('authenticated','private.partner_audit()','execute'), 'audit trigger cannot be called by clients');
select ok(not has_function_privilege('service_role','private.partner_audit()','execute'), 'service role cannot call audit trigger');
select ok(not prosecdef, 'authorization helper is invoker') from pg_proc where oid='private.partner_can_write(uuid)'::regprocedure;
select ok(prosecdef and proconfig @> array['search_path=""'], 'audit definer pins search path') from pg_proc where oid='private.partner_audit()'::regprocedure;
select ok(not exists(select 1 from pg_constraint c where c.contype='f' and c.conrelid in ('merchant_memberships'::regclass,'merchant_categories'::regclass,'merchant_services'::regclass,'merchant_schedules'::regclass,'merchant_audit_events'::regclass) and not exists(select 1 from pg_index i where i.indrelid=c.conrelid and (i.indkey::smallint[])[0:cardinality(c.conkey)-1] @> c.conkey)), 'foreign keys have leading indexes');

insert into auth.users(id,email) values
 ('a0000000-0000-0000-0000-000000000001','owner-a@example.test'),
 ('b0000000-0000-0000-0000-000000000001','owner-b@example.test'),
 ('c0000000-0000-0000-0000-000000000001','unassigned@example.test');
insert into public.merchants(id,display_name) values ('a0000000-0000-0000-0000-000000000002','A'),('b0000000-0000-0000-0000-000000000002','B');
insert into public.merchant_memberships(merchant_id,user_id) values ('a0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001'),('b0000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001');
insert into public.merchant_categories(id,merchant_id) values ('b0000000-0000-0000-0000-000000000003','b0000000-0000-0000-0000-000000000002');
insert into public.merchant_services(id,merchant_id,category_id) values ('b0000000-0000-0000-0000-000000000004','b0000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003');
insert into public.merchant_schedules(merchant_id) values ('b0000000-0000-0000-0000-000000000002');
select throws_ok($$delete from auth.users where id='a0000000-0000-0000-0000-000000000001'$$,'23503',null,'active owner cannot be deleted');
select throws_ok($$update public.merchants set booking_enabled=true$$,'23514',null,'even operator cannot enable bookings');

set local role anon;
select throws_ok($$select * from public.merchants$$,'42501',null,'anonymous direct read denied');
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select results_eq($$select display_name from public.merchants$$,array['A'],'owner sees own tenant only');
select results_eq($$update public.merchants set contact_email='private-contact@example.test',display_name='A changed' returning display_name$$,array['A changed'],'owner updates allowed fields returning');
select results_eq($$insert into public.merchant_categories(id,merchant_id) values ('a0000000-0000-0000-0000-000000000003','a0000000-0000-0000-0000-000000000002') returning id::text$$,array['a0000000-0000-0000-0000-000000000003'],'owner creates category returning');
select results_eq($$update public.merchant_categories set name_ko='카테고리' returning name_ko$$,array['카테고리'],'owner updates category returning');
select results_eq($$insert into public.merchant_services(id,merchant_id,category_id) values ('a0000000-0000-0000-0000-000000000004','a0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000003') returning visibility$$,array['draft'],'empty nullable service draft accepted');
select results_eq($$update public.merchant_services set price_krw=10000,duration_minutes=60 returning price_krw$$,array[10000::bigint],'owner service update returning');
select is_empty($$select id from public.merchants where id='b0000000-0000-0000-0000-000000000002'$$,'cross tenant read empty');
select is_empty($$update public.merchants set display_name='stolen' where id='b0000000-0000-0000-0000-000000000002' returning id$$,'cross tenant update empty');
select throws_ok($$insert into public.merchant_categories(merchant_id) values ('b0000000-0000-0000-0000-000000000002')$$,'42501',null,'cross tenant insert denied');
select is_empty($$select id from public.merchant_services where merchant_id='b0000000-0000-0000-0000-000000000002'$$,'A cannot read B service');
select is_empty($$select merchant_id from public.merchant_schedules where merchant_id='b0000000-0000-0000-0000-000000000002'$$,'A cannot read B schedule');
select is_empty($$update public.merchant_services set name_en='stolen' where merchant_id='b0000000-0000-0000-0000-000000000002' returning id$$,'A cannot update B service');
select is_empty($$update public.merchant_schedules set hours='[]' where merchant_id='b0000000-0000-0000-0000-000000000002' returning merchant_id$$,'A cannot update B schedule');
select throws_ok($$insert into public.merchant_services(merchant_id,category_id) values ('b0000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003')$$,'42501',null,'A cannot create B service');
select throws_ok($$insert into public.merchant_schedules(merchant_id) values ('b0000000-0000-0000-0000-000000000002')$$,'42501',null,'A cannot create B schedule');
select throws_ok($$update public.merchant_categories set merchant_id='b0000000-0000-0000-0000-000000000002'$$,'42501',null,'category tenant transfer denied');
select throws_ok($$update public.merchants set id=gen_random_uuid()$$,'42501',null,'merchant identity protected');
select throws_ok($$update public.merchant_services set merchant_id='b0000000-0000-0000-0000-000000000002'$$,'42501',null,'service tenant transfer denied');
select throws_ok($$insert into public.merchants(display_name) values ('self provision')$$,'42501',null,'owner cannot self provision merchant');
select throws_ok($$update public.merchant_services set id=gen_random_uuid()$$,'42501',null,'service identity protected');
select throws_ok($$update public.merchants set status='active'$$,'42501',null,'status protected');
select throws_ok($$update public.merchants set booking_enabled=true$$,'42501',null,'booking flag protected');
select throws_ok($$update public.merchants set updated_at=now()$$,'42501',null,'timestamps protected');
select throws_ok($$update public.merchant_services set deposit_krw=100$$,'42501',null,'approved deposit protected');
select throws_ok($$insert into public.merchant_services(merchant_id,category_id,deposit_krw) values ('a0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000003',100)$$,'42501',null,'deposit insert protected');
select throws_ok($$insert into public.merchant_memberships(merchant_id,user_id) values ('b0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001')$$,'42501',null,'self grant denied');
select throws_ok($$update public.merchant_memberships set revoked_at=null$$,'42501',null,'ownership change denied');
select throws_ok($$delete from public.merchant_categories$$,'42501',null,'client delete denied');
select throws_ok($$insert into public.merchant_services(merchant_id,category_id) values ('a0000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003')$$,'23503',null,'composite FK rejects cross tenant category');
select throws_ok($$update public.merchant_services set price_krw=0$$,'23514',null,'zero price rejected');
select throws_ok($$update public.merchant_services set duration_minutes=-1$$,'23514',null,'negative duration rejected');
select throws_ok($$update public.merchant_services set cleanup_minutes=9007199254740992$$,'23514',null,'unsafe integer rejected');
select throws_ok($$update public.merchant_services set sort_order=-1$$,'23514',null,'negative sort order rejected');
select throws_ok($$update public.merchant_services set description_en=repeat('x',4001)$$,'23514',null,'description length bounded');
select throws_ok($$update public.merchant_categories set visibility='published'$$,'23514',null,'unknown visibility rejected');
select throws_ok($$update public.merchants set business_types=array['unknown']$$,'23514',null,'unknown business type rejected');
select throws_ok($$update public.merchants set display_name=repeat('x',121)$$,'23514',null,'display length bounded');
select results_eq($$select changed_fields::text from public.merchant_audit_events where entity_table='merchants' and action='UPDATE'$$,array['{contact_email,display_name}'],'audit stores sorted changed keys');
select results_eq($$select actor_user_id::text from public.merchant_audit_events where entity_table='merchants' and action='UPDATE'$$,array['a0000000-0000-0000-0000-000000000001'],'audit records actor');
select ok(not exists(select 1 from public.merchant_audit_events e where row_to_json(e)::text like '%private-contact%'),'audit contains no contact values');
select throws_ok($$insert into public.merchant_audit_events(merchant_id,entity_table,entity_id,action,changed_fields) values ('a0000000-0000-0000-0000-000000000002','merchants','a0000000-0000-0000-0000-000000000002','UPDATE','{}')$$,'42501',null,'audit forgery denied');
select throws_ok($$update public.merchant_audit_events set changed_fields='{}'$$,'42501',null,'audit update denied');
select throws_ok($$delete from public.merchant_audit_events$$,'42501',null,'audit delete denied');
select is_empty($$select id from public.merchant_audit_events where merchant_id='b0000000-0000-0000-0000-000000000002'$$,'audit tenant filtered');
select is((select count(*) from public.merchant_audit_events where entity_table='merchant_services' and action='UPDATE'),1::bigint,'failed writes produce no audit');
update public.merchant_services set price_krw=price_krw;
select is((select count(*) from public.merchant_audit_events where entity_table='merchant_services' and action='UPDATE'),1::bigint,'no op update produces no audit');

set local request.jwt.claim.sub='c0000000-0000-0000-0000-000000000001';
set local request.jwt.claims='{"user_metadata":{"merchant_id":"a0000000-0000-0000-0000-000000000002","role":"owner"}}';
select is_empty($$select id from public.merchants$$,'forged metadata cannot authorize unassigned user');
select is_empty($$select merchant_id from public.merchant_memberships$$,'unassigned sees no memberships');
set local request.jwt.claim.sub='b0000000-0000-0000-0000-000000000001';
select results_eq($$select display_name from public.merchants$$,array['B'],'second owner sees own tenant');
select is_empty($$update public.merchant_categories set name_en='stolen' where merchant_id='a0000000-0000-0000-0000-000000000002' returning id$$,'cross tenant category update empty');
select is_empty($$update public.merchant_services set name_en='stolen' where merchant_id='a0000000-0000-0000-0000-000000000002' returning id$$,'cross tenant service update empty');
select is_empty($$select id from public.merchant_services where merchant_id='a0000000-0000-0000-0000-000000000002'$$,'second owner cannot see first services');
set local request.jwt.claim.sub='';
select is_empty($$select id from public.merchants$$,'null auth uid cannot read');
select throws_ok($$insert into public.merchant_categories(merchant_id) values ('a0000000-0000-0000-0000-000000000002')$$,'42501',null,'null actor cannot write');
set local role postgres;
select throws_ok($$update public.merchant_services set deposit_krw=11000$$,'23514',null,'deposit cannot exceed price');
select throws_ok($$update public.merchant_services set deposit_krw=0$$,'23514',null,'zero deposit rejected');
update public.merchants set status='suspended' where id='a0000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select results_eq($$select display_name from public.merchants$$,array['A changed'],'suspended owner can read');
select is_empty($$update public.merchants set display_name='blocked' returning id$$,'suspended merchant update denied');
select is_empty($$update public.merchant_services set name_en='blocked' returning id$$,'suspended child update denied');
select throws_ok($$insert into public.merchant_categories(merchant_id) values ('a0000000-0000-0000-0000-000000000002')$$,'42501',null,'suspended child insert denied');
set local role postgres;
set local request.jwt.claim.sub='';
update public.merchants set status='closed' where id='a0000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select is_empty($$update public.merchants set display_name='blocked' returning id$$,'closed merchant update denied');
set local role service_role;
set local request.jwt.claim.sub='';
select lives_ok($$update public.merchant_memberships set revoked_at=now() where merchant_id='a0000000-0000-0000-0000-000000000002'$$,'trusted service role revokes membership and audits');
set local role authenticated;
set local request.jwt.claim.sub='a0000000-0000-0000-0000-000000000001';
select is((select count(*) from public.merchant_memberships),1::bigint,'revoked owner sees membership');
select is_empty($$select id from public.merchants$$,'revoked owner sees no merchant');
select is_empty($$select id from public.merchant_categories$$,'revoked owner sees no categories');
select is_empty($$select id from public.merchant_services$$,'revoked owner sees no services');
select is_empty($$select merchant_id from public.merchant_schedules$$,'revoked owner sees no schedules');
select is_empty($$select id from public.merchant_audit_events$$,'revoked owner sees no audit');
set local role postgres;
set local request.jwt.claim.sub='';
select throws_ok($$delete from auth.users where id='a0000000-0000-0000-0000-000000000001'$$,'23503',null,'revoked membership still prevents user deletion');
select lives_ok($$delete from auth.users where id='c0000000-0000-0000-0000-000000000001'$$,'ordinary nonowner deletion works');
select is((select count(*) from public.merchant_audit_events where entity_table='merchant_memberships' and action='UPDATE' and actor_user_id is null),1::bigint,'service role audit actor is null');
insert into auth.users(id,email) values ('e0000000-0000-0000-0000-000000000001','service-provisioned@example.test');
set local role service_role;
select lives_ok($$insert into public.merchants(id) values ('e0000000-0000-0000-0000-000000000002')$$,'service role provisions merchant');
select lives_ok($$insert into public.merchant_memberships(merchant_id,user_id) values ('e0000000-0000-0000-0000-000000000002','e0000000-0000-0000-0000-000000000001')$$,'service role provisions owner membership');
select is((select count(*) from public.merchant_audit_events where merchant_id='e0000000-0000-0000-0000-000000000002' and actor_user_id is null),2::bigint,'service provisioning audited with null actor');
set local request.jwt.claim.sub='b0000000-0000-0000-0000-000000000001';
select throws_ok($$update public.merchants set display_name='wrong actor' where id='e0000000-0000-0000-0000-000000000002'$$,'42501',null,'audit rejects nonmatching nonnull actor even for service role');
set local role authenticated;
set local request.jwt.claim.sub='e0000000-0000-0000-0000-000000000001';
select results_eq($$select id::text from public.merchants$$,array['e0000000-0000-0000-0000-000000000002'],'provisioned owner can read own merchant');
select * from finish();
rollback;
